 * who later logs in.
 */
export const ANON_PAGE_CACHE_CONTROL = "public, max-age=0, s-maxage=300, stale-while-revalidate=3600";

const MOD_PAGE_RE = /^\/mods(?:\/games\/[^/]+(?:\/all)?|\/[^/]+\/[^/]+)?$/;

export function isCacheableModPath(pathname: string): boolean {
  return MOD_PAGE_RE.test(pathname) && pathname !== "/mods/verified";
}

export function isAnonymous(cookieHeader: string | null | undefined, authorization: string | null | undefined, sessionCookieName = "nxeon_session"): boolean {
  if (authorization) return false;
  if (!cookieHeader) return true;
  return !cookieHeader.split(";").some((c) => c.trim().startsWith(`${sessionCookieName}`));
}

/** Header value to add, or null to leave Next's default (private, no-store). Search strings other than ?page are not cached. */
export function anonModCacheControl(opts: { method: string; pathname: string; search: string; cookie: string | null; authorization: string | null; sessionCookieName?: string }): string | null {
  if (opts.method !== "GET" && opts.method !== "HEAD") return null;
  if (!isCacheableModPath(opts.pathname)) return null;
  if (opts.search && !/^\?page=\d{1,5}$/.test(opts.search)) return null;
  if (!isAnonymous(opts.cookie, opts.authorization, opts.sessionCookieName)) return null;
  return ANON_PAGE_CACHE_CONTROL;
}

