export async function nxmMetadata(route: string, over?: SeoOverride): Promise<Metadata> {
  const base = SEO[route];
  if (!base && !over?.title) throw new Error(`nxm SEO: no registry entry for ${route}`);
  const e = { ...base, ...over } as SeoEntry & SeoOverride;
  if (!e.title || !e.description) throw new Error(`nxm SEO: ${route} is missing a title or description`);
  // {price:…} tokens -> live catalogue prices (never a hand-typed figure; see lib/seo-prices.ts)
  e.title = await resolveLivePriceTokens(e.title);
  e.description = await resolveLivePriceTokens(e.description);
  // keep what SERPs show whole: trim trailing clauses/sentences past ~62 / ~158 chars
  e.title = fitTitle(e.title, e.absolute ? "" : " — Nxeon");
  e.description = fitDescription(e.description);
  const title = e.absolute ? { absolute: e.title } : e.title;
  return {
    title,
    description: e.description,
    alternates: { canonical: e.canonical ?? route },
    openGraph: {
      title: e.title,
      description: e.description,
      url: e.canonical ?? route,
      siteName: "Nxeon",
      images: [{ url: e.image ?? DEFAULT_OG }],
      ...(e.type === "article" ? { type: "article" as const, ...(e.article ?? {}) } : { type: "website" as const }),
    },
    twitter: { card: "summary_large_image", title: e.title, description: e.description, images: [e.image ?? DEFAULT_OG] },
    robots: NXM_LIVE && !e.noindex ? { index: true, follow: true } : NXM_LIVE ? { index: false, follow: true } : { index: false, follow: false, nocache: true },
  };
}

